describe('Send messages Tests', function () {
    var timestamp;
    var username;
    var password;
    beforeEach(function () {
        cy.clearLocalStorage();
        cy.clearCookies();
        var run = Cypress.env('run');
        console.log("Running with run: ".concat(run));
        username = Cypress.env("USER_".concat(run, "_USERNAME")) || "KKA";
        password = Cypress.env("USER_".concat(run, "_PASSWORD")) || "Salasana1!";
        console.log("Username: ".concat(username));
        console.log("Password: ".concat(password));
        cy.getAllLocalStorage();
        if (!username || !password) {
            throw new Error("Missing environment variables for USER_".concat(run, "."));
        }
        cy.intercept('POST', '/api/authenticate', function (req) {
            var urlParams = new URLSearchParams(req.body);
            var token = urlParams.get('token');
            if (token === 'valid-token') {
                req.reply({ status: 'ok', credentials: 'valid-token', language: 'en' });
            }
            else {
                req.reply({ status: 'error' });
            }
        });
        cy.viewport(1500, 800);
        cy.visit('http://localhost:3000/auth');
        cy.get('.w-full.p-2.border-gray-300').first().type(username);
        cy.get('.flex > :nth-child(2) > .w-full').type(password);
        cy.get('button[type="submit"]').click();
        cy.wait(200);
        // cy.url().should('not.include', '/auth');
        timestamp = new Date().toLocaleString();
    });
    it("Should send messages from ".concat(username, " to receiver and verify the result"), function () {
        // Get sender and receiver from localStorage
        cy.window().then(function (window) {
            var sender = window.localStorage.getItem('userid');
            var receiver = window.localStorage.getItem('receiver');
            Cypress._.times(100, function (i) {
                for (var n = 1; n <= 5; n++) {
                    cy.wait(200);
                    cy.get(".overflow-y-auto > :nth-child(".concat(n, ") > .justify-between"))
                        .click();
                    var messageContent = "".concat(i, " Hello receiver ").concat(receiver, ", sender ").concat(sender, " - Message #1 [Test - ").concat(timestamp, "] ").concat(i + 1, ", item ").concat(n);
                    cy.get('.m-2').clear().type(messageContent);
                    cy.wait(200);
                    cy.get('.space-y-4 > .md\\:flex-row > .flex').should('be.visible').click();
                    cy.wait(200);
                }
            });
        });
    });
});
